import{R as s,e as a,f as t,U as i}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Cached Forms","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/cached-forms.md","filePath":"frontend/cached-forms.md","lastUpdated":1776774863000}'),n={name:"frontend/cached-forms.md"};function r(o,e,h,l,p,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cached-forms" tabindex="-1">Cached Forms <a class="header-anchor" href="#cached-forms" aria-label="Permalink to &quot;Cached Forms&quot;">​</a></h1><p>Cached forms work well, but they need fresh request-specific values.</p><p>When a page is served from static cache, the HTML may be older than the current request. That matters for things like CSRF tokens, request tokens, and render IDs. If those are stale, a form can fail in ways that look random, especially on cached pages using <a href="https://putyourlightson.com/plugins/blitz" target="_blank" rel="noreferrer">Blitz</a> or another full-page caching layer.</p><h2 id="automatic-refresh" tabindex="-1">Automatic Refresh <a class="header-anchor" href="#automatic-refresh" aria-label="Permalink to &quot;Automatic Refresh&quot;">​</a></h2><p>Formie can handle this for you. When static-cache support is enabled, Formie marks the form as cache-aware and refreshes the tokens it needs when the form is initialized. It also refreshes them again after submit attempts, so retries, page changes, and repeated submissions keep using fresh values.</p><p>Static-cache support is enabled automatically when Blitz is installed and enabled. For other static-cache setups, enable the <code>staticCacheRefreshOnLoad</code> plugin setting in your <a href="/get-started/configuration">Formie config</a>.</p><p>In most cases, Formie can support cached forms without extra JavaScript on the site.</p><h2 id="when-you-might-need-more-control" tabindex="-1">When You Might Need More Control <a class="header-anchor" href="#when-you-might-need-more-control" aria-label="Permalink to &quot;When You Might Need More Control&quot;">​</a></h2><p>If you are taking over Formie&#39;s browser assets yourself, or you are mounting forms through your own browser bundle, make sure token refresh stays enabled. The browser package can receive <code>staticCache</code> and <code>refreshTokens</code> options, but you would normally only set those yourself when you are deliberately replacing Formie&#39;s automatic asset output.</p><p>If you need to control that setup yourself, see:</p><ul><li><a href="/frontend/frontend-assets">Frontend Assets</a></li><li><a href="/templates/render-options">Render Options</a></li><li><a href="/templates/assets">Assets</a></li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>On load, Formie can send a request to the refresh tokens endpoint and update the form with fresh values before the user submits anything.</p><p>After submit attempts, it can refresh them again so the form is ready for the next page submit, retry, or repeated interaction.</p><p>The refresh payload can look like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;csrf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;param&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CRAFT_CSRF_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3YV0bKqQx...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m1f8A2pQ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;renderId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;formie-contact-form-abc123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Formie applies those values back onto the existing form, so the cached HTML can keep working without needing a full re-render.</p>`,17)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
